import{a as e,i as t,r as n,t as r}from"./app-Dkwa1Gla.js";var i=JSON.parse(`{"path":"/%E7%AC%AC09%E7%AB%A0%20%E9%A1%B9%E7%9B%AE%E8%8C%83%E5%9B%B4%E7%AE%A1%E7%90%86/9.3%20%E8%8C%83%E5%9B%B4%E6%8E%A7%E5%88%B6.html","title":"9.3 范围控制","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"第09章 项目范围管理/9.3 范围控制.md"}`),a={name:`9.3 范围控制.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="_9-3-范围控制" tabindex="-1"><a class="header-anchor" href="#_9-3-范围控制"><span>9.3 范围控制</span></a></h1><h2 id="定义" tabindex="-1"><a class="header-anchor" href="#定义"><span>定义</span></a></h2><p>范围控制是指监控项目范围变化，管理范围变更，确保项目范围符合范围基准的过程。</p><h2 id="范围控制的目标" tabindex="-1"><a class="header-anchor" href="#范围控制的目标"><span>范围控制的目标</span></a></h2><h3 id="_1-确保范围基准的完整性" tabindex="-1"><a class="header-anchor" href="#_1-确保范围基准的完整性"><span>1. 确保范围基准的完整性</span></a></h3><ul><li>维护范围基准的准确性</li><li>防止未经授权的变更</li></ul><h3 id="_2-管理范围变更" tabindex="-1"><a class="header-anchor" href="#_2-管理范围变更"><span>2. 管理范围变更</span></a></h3><ul><li>评估变更请求</li><li>批准或拒绝变更</li></ul><h3 id="_3-预防范围蔓延" tabindex="-1"><a class="header-anchor" href="#_3-预防范围蔓延"><span>3. 预防范围蔓延</span></a></h3><ul><li>识别和控制范围蔓延</li><li>确保项目聚焦于目标</li></ul><h3 id="_4-验证项目范围" tabindex="-1"><a class="header-anchor" href="#_4-验证项目范围"><span>4. 验证项目范围</span></a></h3><ul><li>确保项目交付物符合范围要求</li><li>获得客户验收</li></ul><h2 id="范围控制流程" tabindex="-1"><a class="header-anchor" href="#范围控制流程"><span>范围控制流程</span></a></h2><h3 id="_1-监控范围状态" tabindex="-1"><a class="header-anchor" href="#_1-监控范围状态"><span>1. 监控范围状态</span></a></h3><ul><li>收集项目范围执行情况</li><li>对比实际范围与范围基准</li></ul><h3 id="_2-识别范围变更" tabindex="-1"><a class="header-anchor" href="#_2-识别范围变更"><span>2. 识别范围变更</span></a></h3><ul><li>识别范围变化的原因</li><li>判断是否属于范围变更</li></ul><h3 id="_3-提交变更请求" tabindex="-1"><a class="header-anchor" href="#_3-提交变更请求"><span>3. 提交变更请求</span></a></h3><ul><li>填写变更请求表</li><li>说明变更原因和影响</li></ul><h3 id="_4-评估变更影响" tabindex="-1"><a class="header-anchor" href="#_4-评估变更影响"><span>4. 评估变更影响</span></a></h3><ul><li>评估对进度、成本、质量的影响</li><li>分析变更的可行性</li></ul><h3 id="_5-审批变更请求" tabindex="-1"><a class="header-anchor" href="#_5-审批变更请求"><span>5. 审批变更请求</span></a></h3><ul><li>提交变更控制委员会审批</li><li>根据评估结果做出决策</li></ul><h3 id="_6-实施变更" tabindex="-1"><a class="header-anchor" href="#_6-实施变更"><span>6. 实施变更</span></a></h3><ul><li>如果变更获得批准，实施变更</li><li>更新范围基准和相关计划</li></ul><h3 id="_7-验证变更结果" tabindex="-1"><a class="header-anchor" href="#_7-验证变更结果"><span>7. 验证变更结果</span></a></h3><ul><li>验证变更是否按计划实施</li><li>确认变更符合要求</li></ul><h2 id="范围蔓延" tabindex="-1"><a class="header-anchor" href="#范围蔓延"><span>范围蔓延</span></a></h2><h3 id="定义-1" tabindex="-1"><a class="header-anchor" href="#定义-1"><span>定义</span></a></h3><ul><li>项目范围在没有经过正式审批的情况下逐渐扩大</li></ul><h3 id="原因" tabindex="-1"><a class="header-anchor" href="#原因"><span>原因</span></a></h3><ul><li>需求不明确</li><li>客户频繁提出新需求</li><li>项目团队缺乏范围控制意识</li></ul><h3 id="预防措施" tabindex="-1"><a class="header-anchor" href="#预防措施"><span>预防措施</span></a></h3><ul><li>明确项目范围边界</li><li>建立严格的变更控制流程</li><li>加强与客户的沟通</li></ul><h2 id="范围验证" tabindex="-1"><a class="header-anchor" href="#范围验证"><span>范围验证</span></a></h2><h3 id="定义-2" tabindex="-1"><a class="header-anchor" href="#定义-2"><span>定义</span></a></h3><ul><li>对项目可交付成果进行验收的过程</li></ul><h3 id="方法" tabindex="-1"><a class="header-anchor" href="#方法"><span>方法</span></a></h3><ul><li>检查</li><li>审查</li><li>测试</li></ul><h3 id="输出" tabindex="-1"><a class="header-anchor" href="#输出"><span>输出</span></a></h3><ul><li>验收报告</li><li>范围基准更新</li></ul><h2 id="关键考点" tabindex="-1"><a class="header-anchor" href="#关键考点"><span>关键考点</span></a></h2><ol><li><strong>范围控制的流程</strong></li><li><strong>范围蔓延的原因和预防</strong></li><li><strong>范围验证的方法</strong></li></ol><h2 id="记忆口诀" tabindex="-1"><a class="header-anchor" href="#记忆口诀"><span>记忆口诀</span></a></h2><p>范围控制防蔓延，变更流程要严格，验证验收要及时</p><h2 id="典型例题" tabindex="-1"><a class="header-anchor" href="#典型例题"><span>典型例题</span></a></h2><p><strong>例题</strong>：范围控制的主要目的是什么？ A. 扩大项目范围 B. 防止范围蔓延 C. 减少项目成本 D. 加快项目进度</p><p><strong>答案</strong>：B</p><p><strong>解析</strong>：范围控制的主要目的是监控项目范围变化，管理范围变更，防止范围蔓延，确保项目范围符合范围基准。</p>`,49)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};